// Player-requested learning is separate from campaign gates and mission rewards.
const lesson=(id,group,title,page,steps)=>({id,group,title,page,steps});
export const TUTORIAL_LIBRARY=[
 lesson('first-mile','Expedition','Your first mile','guide',['Mount the bike at the opening roadside. Follow the on-screen objective to the salvage crate near Mara.','Recover the spare parts, launch Scout 01, make a short flight and wait for it to dock.','Approach Mara on foot. Her conversation opens the next stretch of the expedition.']),
 lesson('energy','Equipment','Battery, range & pedaling','rig',['Bike charge and trailer reserve are separate stores. Check both before a trip. The range estimate reflects current cargo and terrain.','Motor assist costs energy only for distance actually traveled. Off-road riding costs more; pedaling uses stamina.','Stop and transfer reserve to the bike. If both are low, use solar in daylight, finite fuel, or a discovered source.']),
 lesson('generation','Equipment','Solar, fuel & reserve','rig',['Stop with the trailer attached and open Bike & trailer. Select Solar or Fuel.','Resume the game: generators do not run while a menu holds the expedition. Solar needs daylight; fuel uses the tank.','Transfer reserve when the bike has space. Stow the generator before moving. Water generation unlocks at the Spillway.']),
 lesson('cargo','Equipment','Cargo, mass & the hitch','inventory',['Approach the trailer within 8 m. Open Backpack and choose Trailer storage to transfer cargo.','The trailer holds 60 kg. Heavy cargo raises bike consumption; a loaded Cargo or Utility drone also accelerates and climbs more slowly.','Stop to detach. The trailer remains where you parked it with its contents. Return within 8 m to reattach.']),
 lesson('camo','Fieldcraft','Find and deploy the camo shelter','rig',['Your starting workshop kit includes a patched camouflage shelter. It begins packed, so you will not see it until you deploy it.','Stop beside the bike, turn off fuel generation, then use Deploy camo shelter in Bike & trailer or Swarm Command. Resume to see the canopy.','Stay within 4 m of the rig. It reduces visual detection; it does not stop bullets or hide heat. Moving the bike or starting fuel generation packs it.']),
 lesson('flight','Aircraft','Takeoff, hover & recovery','drones',['Choose an unlocked airframe in Fleet. Launch, then select FPV control to fly it yourself.','In Mode 2, the left stick controls lift/yaw and the right controls forward/strafe. Keyboard: movement keys, Space up, Shift down. Center controls to brake in Stabilized.','Recall returns through the world. Watch until the status says DOCK. Safety returns do not automatically resume jobs.']),
 lesson('acro','Aircraft','Stabilized versus Acro','settings',['Start with Stabilized in Settings: neutral controls brake and level the aircraft.','Acro controls pitch, roll and thrust. A tilted aircraft loses vertical lift unless you compensate. Practice in Flight Yard before committing to a mission.','HOLD or a return command is your recovery action. Camera profile and flight mode are separate controls.']),
 lesson('sensors','Sensing','Thermal, UV & RF','drones',['B cycles only the sensors fitted to the selected airframe or your visor. R takes a reading and spends charge.','Thermal uses relative authored heat. In Light & weather, choose Ironbow, Spectrum, White hot or Black hot. Walls still hide objects.','UV reveals fluorescent paint against a violet scene; it is not a thermal rainbow. RF shows transmitter strength and bearing. Use the Sensor Lab in Flight Yard for practice.']),
 lesson('repair','Aircraft','Hull, battery & repairs','drones',['Inspect each aircraft’s hull, charge and command before launch. These are independent for every drone.','Dock a damaged aircraft before repairing it with steel. Recharge when it has room for more energy.','Low hull, battery or signal can trigger a safety return. Read the reason before sending it out again.']),
 lesson('survey','Aircraft','Survey and return','drones',['After the opening, select an aircraft and assign Survey ahead & return.','The drone flies to its survey point, holds for five seconds, scans and physically returns.','HOLD pauses the job. Resume continues it; recall, cancel or another autonomous order ends it.']),
 lesson('relay','Aircraft','Relay outposts','drones',['A relay extends a route only if each radio hop works. Terrain and buildings still matter.','Assign Relay Outpost after onboarding: the relay lands ahead, then the scout surveys beyond it.','The relay stays deployed with rotors stopped and finite radio drain. Recall it when the route is finished.']),
 lesson('harvest','Equipment','Perch and harvest power','drones',['Unlock Utility and fit the engineer module. Prepare the battery pack and stop near the trailer.','Assign a conductor harvest. Utility approaches, aligns, latches and charges from actual circuit reserves.','Delivery adds trailer energy after physical arrival. HOLD, recall or a fault pauses or ends the task; inspect the reason before resuming.']),
 lesson('fleets','Fleet studio','Build, launch & land 2,000 drones','adminFleet',['F9 opens the live expedition test fleet. Pick a count, choose a program, then Deploy fleet & resume. Commander practice has its own arena.','Apply changes preserves the existing roster. Deploy replaces it when you change fleet size. A large fleet stages its takeoff over twelve seconds.','Land all returns aircraft to reserved pads where they remain visible. Launch parked fleet reuses them. Remove test fleet clears only the temporary test copies.']),
 lesson('layers','Fleet studio','Remove orbit and stack effects','adminFleet',['Formation defines the slots. Movement, choreography and four influences are independent layers. Changing shape does not silently turn those layers off.','Choose None for the layer you want to remove. None / clear all effects clears movement, shows, fields and variance; Apply makes the change live.','Mix field strength, frequency, phase and amount independently. Axis mixes affect the sum of fields. Movement and shows each have separate speed and amount controls.']),
 lesson('variance','Fleet studio','Repeatable variation','adminFleet',['Open Independent effects & variance. Position spread offsets aircraft, phase spread staggers motion and speed spread gives different timing.','The seed makes variations repeatable. Keep spreads small while inspecting spacing and collision behavior.','Reset effects restores zero variation. Use explicit script values such as variance 2, phaseVariance 1, speedVariance 0.1 and seed 37.']),
 lesson('words','Fleet studio','HELLO, then WORLD','adminFleet',['Choose Word sequence and put one word or short message on each line.','Set hold and transition durations. Use a longer transition for a large cast. The same aircraft move between every message.','Use word sequence clears other effects for a readable start. Add layers afterward if wanted. View from the front; depth rows keep large fleets from occupying one stroke.']),
 lesson('script','Fleet studio','Script independent groups','adminFleet',['Open Flight script editor. Select groups such as alpha, bravo, scouts or a drone ID. The addressed group limits the script.','Use formation grid, pattern none, layer 2 wave 8 0.6 and layer 3 vortex 5 0.4. Each layer changes independently.','wait advances the timeline; repeat must be last. layer 2 none removes one field; reset effects clears every effect for the selected group. Errors identify the line.']),
 lesson('music','Fleet studio','Write or upload a soundtrack','adminFleet',['Open Dance & rhythm. Write C4:1 for one beat, C4+E4+G4:2 for a two-beat chord, or R:1 for a rest.','Use composition & enable audio, then resume a running fleet. Notes loop at the chosen BPM. Pausing holds the soundtrack too.','Or attach your audio file. Enter its BPM to time the choreography. Uploads do not detect beats and must be reattached after reopening; written notes are included in saved fleets.']),
 lesson('cinema','Presentation','Cinematic camera','cinematic',['Open Cinematic camera or press F8. Choose the rig, player or test fleet, then choose an orbit, tracking or overhead shot.','The camera observes the live simulation. It does not drive your bike or disable collisions. Fleet framing can include the whole staging grid.','F8 or Exit cinematic restores your normal view and HUD. Escape opens the menu. Reduced motion holds an orbit at a fixed angle.']),
 lesson('world','Expedition','Explore the connected route','map',['The road links camps, service yards and side routes. Scout ahead, park at a safe approach and explore buildings on foot.','Buildings, substantial props and tree trunks block movement. Entrances and authored approach roads remain open. Foliage and road paint are passable.','Existing Basin, Spillway and Black Start regions remain part of the campaign. The map is being expanded around these routes; new dressing does not unlock unfinished regions.'])
];
const valid=id=>TUTORIAL_LIBRARY.some(l=>l.id===id);
export function learningState(raw={}){return {queue:[...new Set((Array.isArray(raw.queue)?raw.queue:[]).filter(valid))].slice(0,20),done:[...new Set((Array.isArray(raw.done)?raw.done:[]).filter(valid))]};}
export function updateLearning(state,action,id){const next=learningState(state);if(!valid(id))return next;if(action==='queue'&&!next.queue.includes(id))next.queue.push(id);if(action==='remove'||action==='done')next.queue=next.queue.filter(x=>x!==id);if(action==='done'&&!next.done.includes(id))next.done.push(id);return next;}
export function renderTutorialLibrary(state,selected=null){const l=TUTORIAL_LIBRARY.find(l=>l.id===selected);return `<section class="tutorialLibrary"><div class="panelTop"><div><span class="eyebrow">PLAYER-REQUESTED LEARNING</span><h2>Tutorial library</h2></div><button data-back>← Back</button></div><p>Browse when you need help, or queue lessons in your own order. Reading a lesson does not reset your expedition or unlock equipment.</p><div class="lessonQueue"><b>Your queue · ${state.queue.length}</b>${state.queue.length?state.queue.map(id=>`<div><button data-learning-open="${id}">${TUTORIAL_LIBRARY.find(l=>l.id===id).title}</button><button data-learning-remove="${id}" aria-label="Remove ${TUTORIAL_LIBRARY.find(l=>l.id===id).title} from queue">Remove</button></div>`).join(''):'<p>Choose Queue on any lesson.</p>'}</div>${l?`<article class="lessonReader" tabindex="-1"><span class="eyebrow">${l.group}</span><h3>${l.title}</h3><ol>${l.steps.map(s=>`<li>${s}</li>`).join('')}</ol><button data-learning-listen="${l.id}">Read aloud</button><button data-nav="${l.page}">Open ${l.page==='adminFleet'?'fleet test controls':l.page==='rig'?'Bike & trailer':l.page==='cinematic'?'cinematic controls':l.page==='drones'?'Fleet operations':l.page}</button><button data-learning-done="${l.id}">Mark read & next queued lesson</button></article>`:''}<label>Find a lesson<input data-learning-search type="search" placeholder="Try battery, orbit, camo or UV"></label><div class="learningGrid">${TUTORIAL_LIBRARY.map(l=>`<article data-learning-card="${l.id}"><span class="eyebrow">${l.group}${state.done.includes(l.id)?' · READ':''}</span><h3>${l.title}</h3><button data-learning-open="${l.id}">Read now</button><button data-learning-queue="${l.id}">${state.queue.includes(l.id)?'Queued':'Queue'}</button></article>`).join('')}</div></section>`;}
